class Solution {
    private boolean dfs(int[][] grid1, int[][] grid2, int r, int c, int m, int n) {
        boolean isSub = (grid1[r][c] == 1);
        grid2[r][c] = 0;
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid2[nr][nc] == 1) {
                boolean childSub = dfs(grid1, grid2, nr, nc, m, n);
                isSub = isSub && childSub;
            }
        }
        return isSub;
    }

    public int countSubIslands(int[][] grid1, int[][] grid2) {
        int m = grid2.length, n = grid2[0].length;
        int ans = 0;

        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid2[r][c] == 1) {
