var countSubIslands = function(grid1, grid2) {
    const m = grid2.length, n = grid2[0].length;
    let ans = 0;

    function dfs(r, c) {
        let isSub = (grid1[r][c] === 1);
        grid2[r][c] = 0;
        const dr = [1, -1, 0, 0];
        const dc = [0, 0, 1, -1];

        for (let k = 0; k < 4; ++k) {
            const nr = r + dr[k], nc = c + dc[k];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid2[nr][nc] === 1) {
                const childSub = dfs(nr, nc);
                isSub = isSub && childSub;
            }
        }
        return isSub;
    }

    for (let r = 0; r < m; ++r) {
        for (let c = 0; c < n; ++c) {
            if (grid2[r][c] === 1) {
                if (dfs(r, c)) {
                    ans++;
                }
            }
        }
    }
    return ans;
};
